a.src:
int fd = open("auth.log", O_WRONLY | O_CREAT | O_TRUNC, 0644);
if (fork() == 0) {          // the child's fd 3 points at the SAME description
    records(fd, "child");    // shared offset: 0 -> 42
    _exit(0);
}
wait(NULL);
records(fd, "parent");       // starts at 42: 42 -> 84

// child  auth 1 ... child  auth 3
// parent auth 1 ... parent auth 3

b.src:
if (fork() == 0) {
    int fd = open("auth.log", O_WRONLY);   // the child's own description
    records(fd, "child");                  // its offset: 0 -> 42
    _exit(0);
}
int fd = open("auth.log", O_WRONLY);       // the parent's own, at 0
wait(NULL);
records(fd, "parent");                     // writes over bytes 0 to 42

// parent auth 1 ... parent auth 3

